{
  "name": "metered-web-broker",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "A neutral one-contract Metered Web Broker: one endpoint returns content + license + settlement receipt. The broker handles the 402s, licenses, identity, budget, and audit.",
  "workspaces": [
    "packages/*"
  ],
  "scripts": {
    "typecheck": "npm run typecheck --workspaces",
    "test": "vitest run",
    "test:watch": "vitest",
    "demo": "tsx scripts/demo.ts",
    "conformance": "tsx packages/conformance/src/cli.ts"
  },
  "devDependencies": {
    "@types/node": "^22.10.0",
    "tsx": "^4.19.0",
    "typescript": "^5.7.0",
    "vitest": "^2.1.0"
  }
}

import {
  BudgetError,
  HeaderRecord,
  IdentityError,
  PaymentRequiredError,
  RailError,
  isBrokerError,
  makeFetchId,
  systemClock,
  type Clock,
  type FetchOutcome,
  type FailureClass,
  type PaymentRail,
  type PaymentRequest,
  type Quote,
  type RailAuthorization,
  type RailSettlement,
  type UrlString,
} from '@mwb/core';
import { BudgetEngine } from '@mwb/budget';
import { AuditLedger } from '@mwb/audit';
import { KeyRing, PACT } from '@mwb/identity';
import {
  deriveObligations,
  parseLicense,
  resolveStoreability,
} from '@mwb/license';

/**
 * The Metered Web Broker orchestrator — the "one contract" call.
 *
 * `Broker.fetch` composes the budget gate, the payment rail, best-effort
 * identity, the license engine, and the audit ledger into a single terminal
 * outcome. The whole thing is designed around one invariant:
 *
 *   every terminal path is one of {fulfilled, blocked, payment-required,
 *   token-rejected} — `error` status is deliberately NOT produced, because a
 *   generic failure hides the cost decision.
 *
 * Pipeline:
 *
 *   1. rail.quote(request)        → quote (the origin's price)
 *   2. budget.preflight(quote)    → `blocked`        if policy denies it
 *   3. rail.authorize(quote)      → `payment-required` if the rail can't pay
 *   4. rail.settle(auth)          → `payment-required` if settlement fails
 *   5. identity.bestEffortSign    → recorded, never a gate
 *   6. origin.fetch(…, settlement) → fulfilled / 402 → payment-required /
 *                                  403 + identity → token-rejected /
 *                                  403 no identity → blocked / else → blocked
 *   7. license.parse + derive from the origin's RSL `Link` header
 *
 * On `fulfilled` only: `BudgetEngine.recordPaid` is called exactly once, and
 * exactly one `AuditLedger` row is recorded for the `fetchId`.
 */

/** The content/SLA source the rail's settled request is sent to. */
export interface OriginResponse {
  httpStatus: number;
  headers: HeaderRecord;
  body: string;
}

export interface OriginClient {
  fetch(req: PaymentRequest): Promise<OriginResponse>;
}

export interface BrokerIdentityOptions {
  /** Subject/tenant to embed in the PACT, if a ring is present and a subject is known. */
  subject?: string;
}

export interface BrokerOptions {
  rail: PaymentRail;
  budget: BudgetEngine;
  ledger: AuditLedger;
  /** Identity vault. Absent ⇒ no identity presented (a 403 then reads as `blocked`). */
  ring?: KeyRing;
  /** Content/SLA source. Required — this is what the broker is metered to fetch. */
  origin: OriginClient;
  clock?: Clock;
  identity?: BrokerIdentityOptions;
  /** Extra headers presented on every origin fetch. Never secrets. */
  headers?: HeaderRecord;
}

/** The broker's terminal decision, decoded by the audit layer and agents. */
export type TerminalKind = 'fulfilled' | 'blocked' | 'payment-required' | 'token-rejected';

/**
 * The Broker. One call composes the whole metered-web decision stack.
 *
 * Injecting every collaborator (rail, budget, ledger, ring, origin, clock)
 * is what makes the terminal-path mapping and the "one row + recordPaid once"
 * guarantee fully testable.
 */
export class Broker {
  private readonly rail: PaymentRail;
  private readonly budget: BudgetEngine;
  private readonly ledger: AuditLedger;
  private readonly ring?: KeyRing;
  private readonly origin: OriginClient;
  private readonly clock: Clock;
  private readonly identityOpts: BrokerIdentityOptions;
  private readonly headers: HeaderRecord;

  /** Cached terminal outcomes keyed by fetchId ⇒ one row + one charge per id. */
  private readonly outcomes = new Map<string, FetchOutcome>();

  constructor(options: BrokerOptions) {
    this.rail = options.rail;
    this.budget = options.budget;
    this.ledger = options.ledger;
    this.ring = options.ring;
    this.origin = options.origin;
    this.clock = options.clock ?? systemClock;
    this.identityOpts = options.identity ?? {};
    this.headers = options.headers ?? {};
  }

  /**
   * Perform one metered fetch and return its terminal outcome.
   *
   * Idempotent by `fetchId`: a second call with the same id returns the
   * cached outcome without re-quoting, re-settling, or charging the meter.
   */
  async fetch(params: {
    url: UrlString;
    fetchId?: string;
    headers?: HeaderRecord;
    tenantId?: string;
    rand?: () => number;
  }): Promise<FetchOutcome> {
    const fetchId = params.fetchId ?? makeFetchId(params.rand);
    const existing = this.outcomes.get(fetchId);
    if (existing) return this.cloneOutcome(existing);

    const startedAt = this.clock.now();
    const tenantId = params.tenantId ?? 'default';

    try {
      const outcome = await this.run(fetchId, startedAt, params.url, tenantId, params.headers);
      // Cache the terminal outcome so a repeat fetchId returns the SAME
      // object without re-quoting, re-settling, or charging the meter.
      this.outcomes.set(fetchId, outcome);
      return outcome;
    } finally {
      // startedAt is carried forward on the outcome's timestamps.
      void startedAt;
    }
  }

  /** The single terminal outcome for a fetchId, or undefined. */
  outcomeFor(fetchId: string): FetchOutcome | undefined {
    const o = this.outcomes.get(fetchId);
    return o ? this.cloneOutcome(o) : undefined;
  }

  /** The one ledger row recorded for a fetchId, or undefined. */
  rowFor(fetchId: string) {
    return this.ledger.entries.find((e) => e.fetchId === fetchId);
  }

  // --- the compose pipeline ---------------------------------------------

  private async run(
    fetchId: string,
    startedAt: string,
    url: UrlString,
    tenantId: string,
    extraHeaders?: HeaderRecord
  ): Promise<FetchOutcome> {
    const req = this.paymentRequest(url, extraHeaders);
    const identity = this.signIdentity(req);

    // 1. Quote the rail — the origin's price, needed to gate on budget.
    const quote = await this.rail.quote(req);

    // 2. Budget gate (the first deny-gate). BudgetError is policy denial.
    try {
      this.budget.preflight(tenantId, quote, url);
    } catch (err) {
      if (err instanceof BudgetError || (err && isBrokerError(err) && err.code === 'CURRENCY_MISMATCH')) {
        return this.denied(fetchId, tenantId, 'blocked',
          err instanceof Error ? err.message : String(err), { url, httpStatus: undefined });
      }
      throw err;
    }

    // 3. Authorize. A rail error here means payment could not be arranged
    //    — a terminal `payment-required` decision, not a thrown fault.
    let authorization: RailAuthorization;
    try {
      authorization = await this.rail.authorize(req, quote);
    } catch (err) {
      return this.denied(fetchId, tenantId, 'payment-required',
        railFault(err, 'authorize', this.rail.id).message, { url, httpStatus: undefined });
    }

    // 4. Settle — the payment commit. Record the settlement ref on the outcome.
    let settlement: RailSettlement;
    try {
      settlement = await this.rail.settle(req, authorization);
    } catch (err) {
      return this.denied(fetchId, tenantId, 'payment-required',
        railFault(err, 'settle', this.rail.id).message, { url, httpStatus: undefined });
    }

    // 5. Content from the origin, settlement headers applied.
    const originResp = await this.origin.fetch({
      ...req,
      headers: { ...req.headers, ...authorization.settlementHeaders },
    });

    // 6. Map the origin's HTTP answer to a terminal class.
    if (!isOk(originResp.httpStatus)) {
      return this.originDenied(fetchId, tenantId, originUrl(originResp, url), originResp.httpStatus, identity != null);
    }

    // fulfilled — charge the meter once and record one row.
    return this.fulfilled({
      url,
      fetchId,
      tenantId,
      quote,
      settlement,
      identity,
      origin: originResp,
      startedAt,
    });
  }

  // --- outcome builders --------------------------------------------------

  private fulfilled(args: {
    url: UrlString;
    fetchId: string;
    tenantId: string;
    quote: Quote;
    settlement: RailSettlement;
    identity?: IdentityPresentation;
    origin: OriginResponse;
    startedAt: string;
  }): FetchOutcome {
    // 7. License — if the origin publishes RSL terms, derive obligations.
    const license = parseOriginLicense(args.origin.headers);
    const obligations = license ? deriveObligations(license) : [];
    const storeable = license ? resolveStoreability(license) : true;

    // Charge the tenant meter exactly once, on fulfillment.
    this.budget.recordPaid(
      args.tenantId,
      { unitsMicros: args.settlement.amountMicros, currency: args.settlement.currency },
      args.url
    );

    const outcome: FetchOutcome = {
      fetchId: args.fetchId,
      status: 'fulfilled',
      reason: 'content released after settlement',
      origin: { url: String(args.url), httpStatus: args.origin.httpStatus },
      content: {
        body: args.origin.body,
        contentType: args.origin.headers['content-type'] ?? 'application/octet-stream',
        storeable,
        attributionNotice: attributionNotice(license),
      },
      license,
      obligations,
      price: { unitsMicros: args.settlement.amountMicros, currency: args.settlement.currency },
      quote: args.quote,
      rail: args.settlement.rail,
      settlementRef: args.settlement.settlementRef,
      identity: args.identity?.keyId ? identityToPresentation(args.identity) : undefined,
      tenantId: args.tenantId,
      timestamps: { startedAt: args.startedAt, completedAt: this.clock.now() },
    };

    this.ledger.record(outcome, { tenantId: args.tenantId });
    return outcome;
  }

  private denied(
    fetchId: string,
    tenantId: string,
    failureClass: FailureClass,
    message: string,
    info: { url: UrlString; httpStatus?: number }
  ): FetchOutcome {
    const outcome: FetchOutcome = {
      fetchId,
      status: 'denied',
      failureClass,
      reason: message,
      error: { code: failureClass, message },
      origin: info.httpStatus != null
        ? { url: String(info.url), httpStatus: info.httpStatus }
        : { url: String(info.url) },
      tenantId,
      timestamps: { startedAt: this.clock.now(), completedAt: this.clock.now() },
    };

    this.ledger.record(outcome, { tenantId });
    return outcome;
  }

  private originDenied(
    fetchId: string,
    tenantId: string,
    url: string,
    httpStatus: number,
    identityPresent: boolean
  ): FetchOutcome {
    let failureClass: FailureClass;
    let message: string;
    let code: string;

    if (httpStatus === 402) {
      failureClass = 'payment-required';
      message = 'origin still demanded payment after settlement (not obtainable)';
      code = 'PAYMENT_REQUIRED';
    } else if (httpStatus === 403 && identityPresent) {
      failureClass = 'token-rejected';
      message = 'origin rejected the presented attestation/identity (HTTP 403)';
      code = 'TOKEN_REJECTED';
    } else if (httpStatus === 403) {
      failureClass = 'blocked';
      message = 'origin blocked the request without a presented identity (HTTP 403)';
      code = 'ORIGIN_BLOCKED';
    } else {
      failureClass = 'blocked';
      message = `origin rejected the request with HTTP ${httpStatus}`;
      code = 'ORIGIN_REJECTED';
    }

    return this.denied(fetchId, tenantId, failureClass, message, { url, httpStatus });
  }

  // --- identity + request helpers ----------------------------------------

  private paymentRequest(url: UrlString, extraHeaders?: HeaderRecord): PaymentRequest {
    return {
      url,
      method: 'GET',
      headers: {
        host: new URL(String(url)).host,
        'user-agent': 'metered-web-broker/0.1',
        ...this.headers,
        ...(extraHeaders ?? {}),
      },
    };
  }

  /**
   * Best-effort identity: sign the presented headers and, when a known
   * subject exists, issue a PACT. Returns undefined when no ring is present,
   * no active key exists, or signing throws. Never a gate.
   */
  private signIdentity(req: PaymentRequest): IdentityPresentation | undefined {
    if (!this.ring) return undefined;

    const keyId = this.ring.active()[0]?.keyId;
    if (!keyId) return undefined;

    // Canonical block the origin can verify: host + date.
    const signingHeaders: HeaderRecord = {
      host: new URL(String(req.url)).host,
      date: this.clock.now(),
      ...req.headers,
    };

    let signedFields: string[];
    try {
      const signed = this.ring.sign(keyId, signingHeaders, ['host', 'date']);
      signedFields = signed.signature.split('fields="')[1]!.split('"')[0]!.split(' ');
    } catch (cause) {
      if (cause instanceof IdentityError) return undefined;
      throw cause;
    }

    let pactToken: string | undefined;
    const subject = this.identityOpts.subject;
    if (subject) {
      try {
        const body = {
          subject,
          grants: [],
          iat: this.clock.now(),
          iss: 'metered-web-broker',
        };
        pactToken = PACT.issue(this.ring, keyId, body).token;
      } catch {
        // Best-effort: a failed PACT issuance is ignored, not a gate.
      }
    }

    return { keyId, algorithm: 'ed25519', signedHeaders: signedFields, timestamp: this.clock.now(), pactToken };
  }

  private cloneOutcome(o: FetchOutcome): FetchOutcome {
    return { ...o, timestamps: { ...o.timestamps } } as FetchOutcome;
  }
}

/** Identity presentation surfaced on a fulfilled outcome. */
interface IdentityPresentation {
  keyId: string;
  algorithm: 'ed25519';
  signedHeaders: string[];
  timestamp: string;
  pactToken?: string;
}

function identityToPresentation(x: IdentityPresentation): FetchOutcome['identity'] {
  return {
    keyId: x.keyId,
    algorithm: x.algorithm,
    signedHeaders: x.signedHeaders,
    timestamp: x.timestamp,
    ...(x.pactToken ? { pactToken: x.pactToken } : {}),
  };
}

function isOk(httpStatus: number): boolean {
  return httpStatus >= 200 && httpStatus < 300;
}

/** A best-effort origin URL for denied rows when the fetch request was dropped. */
function originUrl(resp: OriginResponse, url: UrlString): string {
  return headersUrl(resp) ?? String(url);
}

function headersUrl(resp: OriginResponse): string | undefined {
  const u = resp.headers['location'] ?? resp.headers['Location'];
  if (u) try { return new URL(u).toString(); } catch { return undefined; }
  return undefined;
}

/** Wrap a rail failure as a `payment-required` fault. */
function railFault(err: unknown, step: 'authorize' | 'settle', railId: string): Error {
  if (isBrokerError(err)) return err;
  const cause = err instanceof Error ? err : new Error(String(err));
  return new RailError(`${railId}: ${step} failed`, 'RAIL_ERROR', cause, true);
}

/** Parse the RSL `Link` header from origin response headers, if present. */
function parseOriginLicense(headers: HeaderRecord): FetchOutcome['license'] {
  const link = headers['link'] ?? headers['Link'];
  if (!link) return undefined;
  try {
    return parseLicense(link, { link });
  } catch {
    return undefined; // best-effort: a bad Link is not a terminal failure
  }
}

/** Attribution notice surfaced on fulfilled content, if the license requires it. */
function attributionNotice(
  license: FetchOutcome['license']
): FetchOutcome['content']['attributionNotice'] {
  if (!license) return undefined;
  const clause = license.clauses.find((c) => c.type === 'attribution' && c.value === 'required');
  if (!clause) return undefined;
  const by = typeof clause.params.by === 'string' ? clause.params.by : 'the original author/source';
  return `Attribution required: ${by}`;
}

import { formatMicros } from '@mwb/core';
import type { LedgerEntry } from '@mwb/core';
import { summarize } from './ledger.js';

/**
 * A minimal, dependency-free text dashboard. Deliberately dumb: pipe its
 * output anywhere — CI logs, a status page, an ops channel — and the three
 * failure classes stay visible. The moat is *seeing* these rows, which is
 * what collapses into a generic failure today.
 */
export function renderDashboard(rows: LedgerEntry[], title = 'Metered Web Broker'): string {
  const s = summarize(rows);
  const bar = '─'.repeat(70);
  const lines: string[] = [];
  lines.push(`┌${bar}┐`);
  lines.push(`│ ${title.padEnd(70)} │`);
  lines.push(`└${bar}┘`);
  lines.push(`  total ${s.total}   fulfilled ${s.fulfilled}   denied ${s.denied}`);
  const classes = Object.entries(s.byFailureClass)
    .sort(([a], [b]) => (a < b ? -1 : 1))
    .map(([k, v]) => `${k}=${v}`)
    .join('  ');
  if (classes) lines.push(`  classes  ${classes}`);
  if (s.spendMicros > 0) lines.push(`  spend    ${formatMicros(s.spendMicros)}`);
  lines.push('');

  const cols: Array<[string, (r: LedgerEntry) => string]> = [
    ['seq', (r) => String(r.seq)],
    ['fetch_id', (r) => r.fetchId],
    ['status', (r) => r.status],
    ['class', (r) => r.failureClass ?? '-'],
    ['http', (r) => (r.httpStatus != null ? String(r.httpStatus) : '-')],
    ['price', (r) => (r.priceMicros != null ? formatMicros(r.priceMicros) : '-')],
    ['rail', (r) => r.rail ?? '-'],
  ];
  const widths = cols.map(([label, get]) =>
    Math.max(label.length, ...rows.map((r) => get(r).length))
  );
  const pad = (i: number, t: string) => t.padEnd(widths[i] ?? 0);
  lines.push(cols.map(([label], i) => pad(i, label.toUpperCase())).join('   '));
  lines.push(widths.map((w) => '-'.repeat(w)).join('   '));
  for (const r of rows) lines.push(cols.map(([_l, get], i) => pad(i, get(r))).join('   '));

  return lines.join('\n');
}

import { describe, expect, it } from 'vitest';
import { AuditLedger, reconcile, summarize } from '@mwb/audit';
import { frozenClock, makeFetchId } from '@mwb/core';
import type { FetchOutcome } from '@mwb/core';
import { renderDashboard } from '@mwb/audit';

const clock = frozenClock();

function outcome(partial: Partial<FetchOutcome>): FetchOutcome {
  return {
    fetchId: partial.fetchId ?? makeFetchId(),
    status: 'fulfilled',
    reason: 'ok',
    origin: { url: 'https://news.example.com/wire' },
    timestamps: { startedAt: clock.now(), completedAt: clock.now() },
    ...partial,
  } as FetchOutcome;
}

describe('AuditLedger', () => {
  it('is idempotent per fetchId', () => {
    const ledger = new AuditLedger({ clock });
    const o = { fetchId: 'fetch_fixed1', status: 'fulfilled' as const };
    const a = ledger.record(outcome(o), { tenantId: 't' });
    const b = ledger.record(outcome(o), { tenantId: 't' });
    expect(a).toBe(b);
    expect(ledger.entries.length).toBe(1);
  });

  it('keeps seq gap-free', () => {
    const ledger = new AuditLedger({ clock });
    for (let i = 0; i < 5; i++) ledger.record(outcome({ fetchId: `fetch_n${i}` }));
    expect(ledger.entries.map((e) => e.seq)).toEqual([1, 2, 3, 4, 5]);
    expect(ledger.lastSeq()).toBe(5);
  });

  it('summarizes failure classes and spend separately', () => {
    const ledger = new AuditLedger({ clock });
    ledger.record(outcome({ fetchId: 'f1', price: { unitsMicros: 1000, currency: 'USD' }, rail: 'x402', settlementRef: 's1' }));
    ledger.record(outcome({ fetchId: 'f2', status: 'denied', failureClass: 'blocked', reason: 'policy' }));
    ledger.record(outcome({ fetchId: 'f3', status: 'denied', failureClass: 'payment-required', httpStatus: 402 as unknown as number, origin: { url: 'u', httpStatus: 402 } }));
    ledger.record(outcome({ fetchId: 'f4', status: 'denied', failureClass: 'token-rejected', origin: { url: 'u', httpStatus: 403 } }));
    const s = summarize(ledger.entries);
    expect(s.total).toBe(4);
    expect(s.fulfilled).toBe(1);
    expect(s.denied).toBe(3);
    expect(s.byFailureClass).toEqual({ blocked: 1, 'payment-required': 1, 'token-rejected': 1 });
    expect(s.spendMicros).toBe(1000);
  });
});

describe('reconcile', () => {
  it('passes on a healthy ledger', () => {
    const ledger = new AuditLedger({ clock });
    ledger.record(outcome({ fetchId: 'f1', price: { unitsMicros: 1000, currency: 'USD' }, settlementRef: 'settle_x', rail: 'x402' }));
    ledger.record(outcome({ fetchId: 'f2', status: 'denied', failureClass: 'blocked' }));
    const rep = reconcile(ledger.entries);
    expect(rep.ok).toBe(true);
    expect(rep.problems).toEqual([]);
  });

  it('flags a fulfilled row missing settlementRef', () => {
    const ledger = new AuditLedger({ clock });
    ledger.record(outcome({ fetchId: 'f1', price: { unitsMicros: 1000, currency: 'USD' } }));
    const rep = reconcile(ledger.entries);
    expect(rep.ok).toBe(false);
    expect(rep.checks.fulfilledHasSettlement).toBe(false);
  });

  it('flags a denied row without a failure class', () => {
    const ledger = new AuditLedger({ clock });
    ledger.record(outcome({ fetchId: 'f1', status: 'denied' }));
    const rep = reconcile(ledger.entries);
    expect(rep.checks.deniedHasFailureClass).toBe(false);
  });

  it('flags a seq gap', () => {
    const rows = [
      { seq: 1, fetchId: 'a', tenantId: 't', url: 'u', status: 'denied', failureClass: 'blocked', startedAt: 't', completedAt: 't', recordedAt: 't' },
      { seq: 3, fetchId: 'b', tenantId: 't', url: 'u', status: 'denied', failureClass: 'blocked', startedAt: 't', completedAt: 't', recordedAt: 't' },
    ];
    const rep = reconcile(rows);
    expect(rep.checks.seqGapFree).toBe(false);
  });
});

describe('dashboard', () => {
  it('renders a readable report with all three classes', () => {
    const ledger = new AuditLedger({ clock });
    ledger.record(outcome({ fetchId: 'f1', price: { unitsMicros: 1000, currency: 'USD' }, rail: 'x402', settlementRef: 's' }));
    ledger.record(outcome({ fetchId: 'f2', status: 'denied', failureClass: 'blocked' }));
    ledger.record(outcome({ fetchId: 'f3', status: 'denied', failureClass: 'payment-required' }));
    const text = renderDashboard(ledger.entries);
    expect(text).toContain('blocked=1');
    expect(text).toContain('payment-required=1');
    expect(text).toContain('total 3');
    expect(text).toContain('0.01 USD');
  });
});

import { describe, expect, it } from 'vitest';
import { AuditLedger, reconcile, summarize } from '@mwb/audit';
import { BudgetEngine, defaultPolicy } from '@mwb/budget';
import { InMemoryRail } from '@mwb/rails';
import { KeyRing } from '@mwb/identity';
import { frozenClock, makeFetchId, type Clock } from '@mwb/core';
import type { OriginClient, OriginResponse, TerminalKind } from '@mwb/gateway';
import { Broker } from '@mwb/gateway';

const clock = frozenClock();

const PRICE = 5000; // 5000 micros
const URL = 'https://api.example.com/data';

/** A minimal origin that returns whatever status we configure. */
function origin(response: Partial<OriginResponse> = {}): OriginResponse {
  return {
    httpStatus: 200,
    headers: {},
    body: '<html>ok</html>',
    ...response,
  };
}

/** Wrap an OriginResponse in the minimal OriginClient the broker calls. */
function client(resp: OriginResponse = origin()): OriginClient {
  return { fetch: () => Promise.resolve(resp) };
}

function make({
  price = PRICE,
  failureMode = 'none',
  currency,
  ring = false,
  origin: resp = origin(),
}: {
  price?: number;
  failureMode?: 'none' | 'quote' | 'authorize' | 'settle';
  currency?: string;
  ring?: boolean;
  origin?: OriginResponse;
} = {}) {
  const budget = new BudgetEngine({ policy: defaultPolicy, clock });
  const ledger = new AuditLedger({ clock });
  const rail = new InMemoryRail({
    id: 'x402',
    priceMicros: price,
    currency: currency ?? defaultPolicy.currency,
    clock,
    settlementSeed: 'seed',
    failureMode,
  });
  const opts: ConstructorParameters<typeof Broker>[0] = {
    rail,
    budget,
    ledger,
    origin: { fetch: () => Promise.resolve(resp) },
    clock,
  };
  if (ring) {
    const r = new KeyRing(clock);
    r.issue({ keyId: 'test-key' });
    opts.ring = r;
  }
  return { budget, ledger, rail, opts };
}

function run(opts: ConstructorParameters<typeof Broker>[0], params?: { fetchId?: string; tenantId?: string }) {
  const b = new Broker(opts);
  const f = params?.fetchId ?? makeFetchId();
  return {
    broker: b,
    outcome: b.fetch({ url: URL, fetchId: f, tenantId: params?.tenantId }),
  };
}

