/**
 * Money as integer micro-units (1/1,000,000 of a currency unit), like x402.
 * Avoids floating point in anything that touches a ceiling or a ledger.
 */
export type Micros = number;

export const MICRO_PER_UNIT = 1_000_000;

export interface Price {
  unitsMicros: number;
  currency: string;
}

export interface Quote extends Price {
  rail: string;
  settlement: 'immediate' | 'batch';
  expiresAt?: string;
}

export function micros(units: number): Micros {
  if (!Number.isFinite(units)) throw new RangeError(`micros(): non-finite unit value ${units}`);
  const v = Math.round(units * MICRO_PER_UNIT);
  if (!Number.isSafeInteger(v)) throw new RangeError(`micros(): precision overflow for ${units}`);
  return v;
}

export function formatMicros(micros_: Micros, currency = 'USD'): string {
  return `${(micros_ / MICRO_PER_UNIT).toFixed(2)} ${currency}`;
}

export function addMicros(a: Micros, b: Micros): Micros {
  if (!Number.isSafeInteger(a) || !Number.isSafeInteger(b)) {
    throw new RangeError('addMicros(): unsafe integer input');
  }
  return a + b;
}

import { createPrivateKey, createPublicKey, generateKeyPairSync, sign, verify } from 'node:crypto';
import { IdentityError, systemClock } from '@mwb/core';
import type { Clock, HeaderRecord } from '@mwb/core';

/**
 * Identity & Attestation — Ed25519 key lifecycle as a first-class concern.
 *
 *  - issue: mint a keypair with tight expiry (default 1h, hard cap 24h)
 *  - rotate: mark the current key revoked, mint the next — old key stays
 *    verifiable for in-flight settlements
 *  - sign: http-message-signatures style signature over selected headers
 *  - PACT: broker-issued attestation token the origin can verify against
 *    the public directory
 *
 * The directory payload below is what the broker serves at
 * `/.well-known/agent-identity` so origins can look up the public key
 * without a side channel.
 *
 * Draft-caveat discipline: build against the *patterns* of Web Bot Auth
 * and PACT, not their draft field names.
 */

export type B64Url = string;

export function b64url(bytes: Uint8Array): B64Url {
  return Buffer.from(bytes).toString('base64url');
}

export function fromB64url(s: B64Url): Uint8Array {
  return new Uint8Array(Buffer.from(s, 'base64url'));
}

export interface KeyPair {
  /** Broker-chosen stable key id — this is what the audit trail references. */
  keyId: string;
  algorithm: 'ed25519';
  /** 32-byte public key (JWK `x`), base64url. */
  publicRaw: B64Url;
  /** 32-byte seed (JWK `d`), base64url. Never leaves the broker. */
  privateRaw: B64Url;
  createdAt: string;
  expiresAt: string;
  revokedAt?: string;
}

export interface IssueOptions {
  keyId?: string;
  /** Lifetime. Default 1h; hard cap 24h (tight-expiry discipline). */
  ttlMs?: number;
}

const MAX_TTL_MS = 24 * 3_600_000;
const DEFAULT_TTL_MS = 3_600_000;

/**
 * The broker's identity vault. Every key the broker has ever issued, in
 * memory. Keys past `expiresAt` or with `revokedAt` set refuse to sign;
 * the ring keeps them so in-flight signatures still verify.
 */
export class KeyRing {
  readonly clock: Clock;
  private readonly keys = new Map<string, KeyPair>();
  private counter = 0;

  constructor(clock: Clock = systemClock) {
    this.clock = clock;
  }

  /** Mint a fresh Ed25519 keypair with tight expiry. */
  issue(options: IssueOptions = {}): KeyPair {
    const now = this.clock.now();
    const nowMs = Date.parse(now);
    const ttl = Math.min(Math.max(1_000, options.ttlMs ?? DEFAULT_TTL_MS), MAX_TTL_MS);
    const { publicKey, privateKey } = generateKeyPairSync('ed25519');
    const pubJwk = publicKey.export({ format: 'jwk' }) as JsonWebKey;
    const privJwk = privateKey.export({ format: 'jwk' }) as JsonWebKey;
    if (!pubJwk.x || !privJwk.d) {
      throw new IdentityError('failed to export Ed25519 JWK', 'IDENTITY_EXPORT');
    }
    this.counter += 1;
    const keyId = options.keyId ?? `key_${this.counter.toString(36)}_${nowMs.toString(36)}`;
    if (this.keys.has(keyId)) {
      throw new IdentityError(`keyId already in use: ${keyId}`, 'IDENTITY_DUPLICATE');
    }
    const kp: KeyPair = {
      keyId,
      algorithm: 'ed25519',
      publicRaw: b64url(fromB64url(pubJwk.x as string)),
      privateRaw: b64url(fromB64url(privJwk.d as string)),
      createdAt: now,
      expiresAt: new Date(nowMs + ttl).toISOString(),
    };
    this.keys.set(keyId, kp);
    return kp;
  }

  /**
   * Rotate: mark the current active key revoked, mint a fresh one. The old
   * key remains verifiable until the caller drops it — that is what lets
   * in-flight settlements close out cleanly.
   */
  rotate(options: IssueOptions = {}): { previous?: KeyPair; next: KeyPair } {
    const current = this.active().sort((a, b) => b.createdAt.localeCompare(a.createdAt))[0];
    if (current) current.revokedAt = this.clock.now();
    const next = this.issue(options);
    return { previous: current, next };
  }

  get(keyId: string): KeyPair {
    const kp = this.keys.get(keyId);
    if (!kp) throw new IdentityError(`unknown key: ${keyId}`, 'IDENTITY_UNKNOWN');
    return kp;
  }

  all(): KeyPair[] {
    return [...this.keys.values()];
  }

  active(): KeyPair[] {
    const now = Date.parse(this.clock.now());
    return this.all().filter((k) => !k.revokedAt && Date.parse(k.expiresAt) >= now);
  }

  /**
   * Sign a canonicalized header block.
   *
   * Canonicalization: lowercase header names, lexicographic order, one
   * `name: value` per line, joined with `\n`, trailing `\n`. This is the
   * *pattern* of http-message-signatures; the exact wire form tracks
   * whatever draft the origin validates against.
   *
   * Returns:
   *  - `signature`: the wire header value to attach
   *  - `message`: the canonical signing string (for replay/debug)
   *  - `signedAt`: broker timestamp
   */
  sign(
    keyId: string,
    headers: HeaderRecord,
    signedFields: string[] = ['host', 'date']
  ): { signature: string; message: string; signedAt: string } {
    const kp = this.get(keyId);
    const now = this.clock.now();
    if (kp.revokedAt) throw new IdentityError(`key revoked: ${keyId}`, 'IDENTITY_REVOKED');
    if (Date.parse(kp.expiresAt) < Date.parse(now)) {
      throw new IdentityError(`key expired: ${keyId}`, 'IDENTITY_EXPIRED');
    }

    const fields = signedFields.map((f) => f.toLowerCase()).sort();
    const normed = normHeaders(headers);
    const lines = fields.map((f) => {
      const v = normed.get(f);
      if (v === undefined) throw new IdentityError(`missing header to sign: ${f}`, 'IDENTITY_FIELD');
      return `${f}: ${v}`;
    });
    const message = lines.join('\n') + '\n';

    const seed = fromB64url(kp.privateRaw);
    const keyObject = createPrivateKey({
      key: {
        kty: 'OKP',
        crv: 'Ed25519',
        d: kp.privateRaw,
        x: kp.publicRaw,
      } as JsonWebKey,
      format: 'jwk',
    });
    const sigBytes = Buffer.from(sign(null, Buffer.from(message, 'utf8'), keyObject));
    const sig = b64url(new Uint8Array(sigBytes));
    const signature = `keyId="${keyId}";algorithm="ed25519";fields="${fields.join(' ')}";signature="${sig}"`;
    return { signature, message, signedAt: now };
  }

  /** Verify a signature produced by this ring. */
  verify(keyId: string, message: string, sigB64url: B64Url): boolean {
    try {
      const kp = this.get(keyId);
      const keyObject = createPublicKey({
        key: {
          kty: 'OKP',
          crv: 'Ed25519',
          x: kp.publicRaw,
        } as JsonWebKey,
        format: 'jwk',
      });
      return verify(null, Buffer.from(message, 'utf8'), keyObject, Buffer.from(fromB64url(sigB64url)));
    } catch {
      return false;
    }
  }

  /**
   * Directory the broker serves at `/.well-known/agent-identity`. Only
   * active keys appear, sorted by keyId for stable diffs.
   */
  directory(): {
    format: 'agent-identity-directory';
    agentIdentity: Array<{ keyId: string; alg: 'Ed25519'; pubkey: string; expires: string }>;
  } {
    return {
      format: 'agent-identity-directory',
      agentIdentity: this.active()
        .slice()
        .sort((a, b) => a.keyId.localeCompare(b.keyId))
        .map((k) => ({
          keyId: k.keyId,
          alg: 'Ed25519' as const,
          pubkey: k.publicRaw,
          expires: k.expiresAt,
        })),
    };
  }
}

function normHeaders(headers: HeaderRecord): Map<string, string> {
  const out = new Map<string, string>();
  for (const [k, v] of Object.entries(headers ?? {})) out.set(k.toLowerCase(), v);
  return out;
}

/**
 * A PACT is a broker-issued, key-signed attestation token. Wire format is
 * intentionally minimal:
 *
 *   <base64url(json of claims)> . <keyId> . <base64url(signature)>
 *
 * where the signature covers `<claimsBytes>` exactly (so origin replays
 * the same bytes it received, and the keyId selects the ring entry). When
 * the PACT spec stabilizes, this token shape stays — only the payload
 * inside changes.
 */
export class PACT {
  static issue(ring: KeyRing, keyId: string, claims: Record<string, unknown>): {
    token: string;
    message: string;
    signedAt: string;
  } {
    const body = JSON.stringify(claims);
    const b64 = Buffer.from(body, 'utf8').toString('base64url');
    const sigB64url = b64url(signPactBody(body, ring, keyId));
    return {
      token: `${b64}.${keyId}.${sigB64url}`,
      message: body,
      signedAt: ring.clock.now(),
    };
  }

  static parse(token: string): { claims: Record<string, unknown>; keyId: string; signature: B64Url; body: string } {
    const parts = token.split('.');
    if (parts.length !== 3) throw new IdentityError('malformed PACT token (expected 3 parts)', 'PACT_MALFORMED');
    const [bodyB64, keyId, signature] = parts as [B64Url, string, B64Url];
    const body = Buffer.from(bodyB64, 'base64url').toString('utf8');
    let claims: Record<string, unknown>;
    try {
      claims = JSON.parse(body) as Record<string, unknown>;
    } catch (cause) {
      throw new IdentityError('PACT claims are not valid JSON', 'PACT_CLAIMS', cause);
    }
    return { claims, keyId, signature, body };
  }

  static verify(token: string, ring: KeyRing): { valid: boolean; reason?: string; claims?: Record<string, unknown> } {
    const { claims, keyId, signature, body } = PACT.parse(token);
    if (new Date(claims.exp as string).getTime() < Date.parse(ring.clock.now())) {
      return { valid: false, reason: 'pact-expired', claims };
    }
    const ok = signPactVerify(body, ring, keyId, signature);
    if (!ok) return { valid: false, reason: 'signature-mismatch', claims };
    return { valid: true, claims };
  }
}

/** Sign the exact bytes of a PACT body (not a header canonicalization). */
function signPactBody(body: string, ring: KeyRing, keyId: string): Uint8Array {
  const kp = ring.get(keyId);
  const keyObject = createPrivateKey({
    key: {
      kty: 'OKP',
      crv: 'Ed25519',
      d: kp.privateRaw,
      x: kp.publicRaw,
    } as JsonWebKey,
    format: 'jwk',
  });
  return new Uint8Array(sign(null, Buffer.from(body, 'utf8'), keyObject));
}

function signPactVerify(body: string, ring: KeyRing, keyId: string, sigB64url: B64Url): boolean {
  try {
    const kp = ring.get(keyId);
    const keyObject = createPublicKey({
      key: {
        kty: 'OKP',
        crv: 'Ed25519',
        x: kp.publicRaw,
      } as JsonWebKey,
      format: 'jwk',
    });
    return verify(null, Buffer.from(body, 'utf8'), keyObject, Buffer.from(fromB64url(sigB64url)));
  } catch {
    return false;
  }
}

// PACT helpers — small indirections so KeyRing stays readable. The `keyId`
// is already on the ring, so these resolve via the ring.
function require_ring_sign(_ring: KeyRing): { signature: string } {
  return { signature: '' };
}

function signMessage(keyId: string, message: string, ring: KeyRing): { signature: B64Url } {
  const kp = ring.get(keyId);
  const keyObject = createPrivateKey({
    key: {
      kty: 'OKP',
      crv: 'Ed25519',
      d: kp.privateRaw,
      x: kp.publicRaw,
    } as JsonWebKey,
    format: 'jwk',
  });
  return { signature: b64url(new Uint8Array(sign(null, Buffer.from(message, 'utf8'), keyObject))) };
}

/** Convenience: issue a common-claims PACT with standard expiry. */
export function issuePact(
  ring: KeyRing,
  keyId: string,
  subject: string,
  grants?: Array<{ domain?: string; scope?: string; spendCeilingMicros?: number }>
): { token: string; body: string } {
  const nowMs = Date.parse(ring.clock.now());
  const body = {
    subject,
    grants: grants ?? [],
    iat: new Date(nowMs).toISOString(),
    exp: new Date(Math.min(nowMs + 15 * 60_000, Date.parse(ring.get(keyId).expiresAt))).toISOString(),
    iss: 'metered-web-broker',
  };
  return PACT.issue(ring, keyId, body);
}

import { LicenseError } from '@mwb/core';
import type { License, LicenseObligation, RslClause } from '@mwb/core';

/**
 * License Engine — the broker's compliance layer.
 *
 * Three jobs, all read-only with respect to the network:
 *   1. `parseLicense`     — turn a raw RSL source (a parsed body or a
 *      `Link` header) into a typed `License`.
 *   2. `deriveObligations` — read those terms and produce the concrete,
 *      fetch-scoped obligations the caller must satisfy (attribution,
 *      no-store, pay-per-inference budget, …).
 *   3. `enforce` / `resolveStoreability` — post-fetch checks: did the
 *      caller's actions violate a term?
 *
 * RSL (Really Simple Licensing) terms ride in an HTTP `Link` header, e.g.
 *
 *     Link: <https://licenses.example/r/73>; rel="type:license-terms"
 *
 * with a JSON body that carries the `terms` array. This module builds
 * against that *pattern*; draft field names may drift, so parsing is
 * defensive. Draft-caveat discipline: parse against the shape above, never
 * a draft's exact wire grammar.
 */

/** A clause, as it appears in an RSL `terms` array. */
export interface RslTermInput {
  type: string;
  value?: boolean | number | string;
  params?: Record<string, string | number>;
}

/** A parsed RSL body, matching the accepted JSON shape. */
export interface RslBodyLike {
  draft?: string;
  id?: string;
  title?: string;
  publishedAt?: string;
  terms?: RslTermInput[];
}

export interface LicenseParseOptions {
  /** A `Link` header (or just its URL) identifying the terms document. */
  link?: string;
  /**
   * The raw source string, preserved verbatim on the parsed License for the
   * audit trail. Defaults to whatever was parsed if it was a string.
   */
  rawSource?: string;
}

/**
 * Parse an RSL source into a License.
 *
 * Accepts:
 *  - a JSON string with a `terms` array (or an `RslBodyLike` object)
 *  - a `Link` header string such as
 *    `<https://licenses.example/r/73>; rel="type:license-terms"`
 *  - `options.link` to attach a terms id when the body carries no `id`.
 */
export function parseLicense(
  source: string | RslBodyLike,
  options: LicenseParseOptions = {}
): License {
  let body: RslBodyLike = { ...(source && typeof source === 'object' ? source : {}) };
  let rawSource: string | undefined = options.rawSource;

  if (typeof source === 'string') {
    const s = source.trim();
    if (s.startsWith('{')) {
      try {
        body = { ...(JSON.parse(s) as RslBodyLike) };
      } catch (cause) {
        throw new LicenseError(`RSL body is not valid JSON: ${s}`, 'RSL_PARSE', cause);
      }
      rawSource ??= source;
    } else {
      // It is a Link header (or bare URL) identifying the terms doc.
      const link = extractLink(s);
      body.id = body.id ?? link.id;
      body.draft = body.draft ?? link.draft;
      rawSource ??= source;
    }
  }

  const id = body.id?.trim() || linkId(body.link as string | undefined);
  if (!id) {
    throw new LicenseError('RSL source carried no license identifier', 'RSL_NO_ID');
  }

  return {
    draft: body.draft?.trim() || 'urn:rsl:draft:unregistered',
    id,
    title: body.title,
    publishedAt: body.publishedAt,
    clauses: normalizeClauses(body.terms),
    rawSource: rawSource ?? body.rawSource ?? `<${id}>`,
  };
}

/**
 * Derive the fetch-scoped obligations from a license. An empty terms array
 * yields no obligations; the broker still surfaces the `License` so the
 * caller can see what it is (not) bound to.
 */
export function deriveObligations(license: License): LicenseObligation[] {
  const out: LicenseObligation[] = [];
  for (const clause of license.clauses) {
    const { instruction, kind } = clauseToObligation(clause.type, clause.params);
    if (instruction) out.push({ clause: clause.type, kind, instruction });
  }
  return out;
}

/**
 * Whether the broker may mark the fetched content storeable given the
 * license. A `no-store` marked `forbidden` makes it non-storeable; anything
 * else leaves storeability to the caller.
 */
export function resolveStoreability(license: License): boolean {
  return !license.clauses.some((c) => c.type === 'no-store' && c.value === 'forbidden');
}

/** Post-fetch actions the caller may have taken. */
export interface EnforcementActions {
  /** Did the caller store/cache the content? */
  store?: boolean;
  /** Attribution notice included when storing, if any (non-empty ⇒ provided). */
  attribution?: string;
  /** Is the usage commercial? */
  commercialUse?: boolean;
  /** Did the caller produce a derivative work from stored content? */
  derived?: boolean;
  /** Number of model inferences run, if any. */
  inferenceCount?: number;
}

export interface EnforcementResult {
  pass: boolean;
  violations: string[];
  obligations: LicenseObligation[];
}

/**
 * Check the caller's post-fetch actions against the license. Returns the
 * derived obligations plus any violations — the broker surfaces this so a
 * call that "worked" can still report a compliance problem.
 *
 * Pay-per-inference is advisory (a budget, not a hard gate): the settlement
 * row is the proof of payment, so the engine never blocks on it.
 */
export function enforce(
  license: License,
  actions: EnforcementActions = {}
): EnforcementResult {
  const violations: string[] = [];

  for (const clause of license.clauses) {
    if (clause.type === 'no-store' && clause.value === 'forbidden' && actions.store) {
      violations.push('no-store: content must not be stored, but store was requested');
    }
    if (clause.type === 'no-commercial-use' && clause.value === 'forbidden' && actions.commercialUse) {
      violations.push('no-commercial-use: usage is commercial, which the license forbids');
    }
    if (
      clause.type === 'no-derivative-works' &&
      clause.value === 'forbidden' &&
      actions.store &&
      actions.derived
    ) {
      violations.push('no-derivative-works: content was stored and transformed');
    }
  }

  const wantsAttribution = license.clauses.some((c) => c.type === 'attribution' && c.value === 'required');
  if (wantsAttribution && actions.store && !attributionProvided(actions)) {
    violations.push('attribution: content was stored without the required attribution notice');
  }

  return { pass: violations.length === 0, violations, obligations: deriveObligations(license) };
}

function attributionProvided(actions: EnforcementActions): boolean {
  return typeof actions.attribution === 'string' && actions.attribution.length > 0;
}

// --- clause mapping -------------------------------------------------------

/** Translate a single clause to the obligation it imposes, if any. */
function clauseToObligation(
  type: string,
  params?: Record<string, string | number>
): { instruction?: string; kind: LicenseObligation['kind'] } {
  switch (type) {
    case 'attribution':
      if (params?.by) return { kind: 'notice', instruction: `Include attribution to ${params.by} when using this content.` };
      return { kind: 'notice', instruction: 'Include attribution when using this content.' };
    case 'no-store':
      return { kind: 'store-prohibited', instruction: 'Do not store or cache this content.' };
    case 'no-derivative-works':
      return { kind: 'forbidden', instruction: 'Do not create derivative works from this content.' };
    case 'no-commercial-use':
      return { kind: 'forbidden', instruction: 'Commercial use of this content is forbidden.' };
    case 'redistribution':
      return { kind: 'forbidden', instruction: 'Redistribution of this content is forbidden.' };
    default:
      return { kind: 'notice', instruction: `License term ${type} applies; review its conditions.` };
  }
}

// --- helpers --------------------------------------------------------------

/** RSL treats a bare clause as required; the engine is predictable about it. */
function normalizeClauses(terms?: RslTermInput[]): RslClause[] {
  if (!terms) return [];
  const out: RslClause[] = [];
  for (const t of terms) {
    if (!t || typeof t.type !== 'string' || !t.type) {
      throw new LicenseError(`RSL clause is missing a type: ${JSON.stringify(t)}`, 'RSL_BAD_CLAUSE');
    }
    out.push({
      type: t.type,
      value: t.value ?? 'required',
      params: t.params ?? {},
    });
  }
  return out;
}

/** Parse a `Link` header (or bare URL) into { id, draft }. */
function extractLink(link: string): { id: string; draft?: string } {
  const url = linkUrl(link);
  if (!url) return { id: '' };
  return { id: slugFromUrl(url), draft: draftFromUrl(url) };
}

/** A `Link: <url>; rel="..."` or a bare `<url>` / url → the URL string. */
function linkUrl(link: string): string {
  const brace = link.match(/<([^>]*)>/);
  if (brace) return brace[1]!;
  const token = (link.trim().split(/\s|;/)[0] ?? '').trim();
  return token.startsWith('http') ? token : '';
}

/** https://h.example.com/r/73 → https://h.example.com/r/73. */
function slugFromUrl(url: string): string {
  try {
    return new URL(url).href;
  } catch {
    return url;
  }
}

/** A draft label is best-effort; used only if the body carried no draft. */
function draftFromUrl(url: string): string | undefined {
  try {
    return new URL(url).hostname || undefined;
  } catch {
    return undefined;
  }
}

/** Alias used by the top-level parse path for a link given via options. */
function linkId(link?: string): string {
  if (!link) return '';
  return extractLink(link.trim()).id;
}

import type {
  Clock,
  FetchOutcome,
  FailureClass,
  LedgerEntry,
} from '@mwb/core';

/**
 * The ledger is the broker's source of truth: every fetch the broker
 * attempted — fulfilled, denied, failed — appears exactly once.
 *
 * `seq` is monotonically increasing and gap-free; that invariant is what the
 * reconciliation step verifies. If the broker crashes or an origin
 * settlement is missing, reconciliation surfaces it instead of hiding it.
 */
export class AuditLedger {
  readonly entries: LedgerEntry[] = [];
  private seq = 0;
  private readonly clock: Clock;

  constructor(options?: { clock?: Clock }) {
    this.clock = options?.clock ?? { now: () => new Date().toISOString() };
  }

  /** Append one row for one fetch attempt. Idempotent per fetchId. */
  record(outcome: FetchOutcome, options?: { tenantId?: string }): LedgerEntry {
    const existing = this.entries.find((e) => e.fetchId === outcome.fetchId);
    if (existing) return existing;

    this.seq += 1;
    const now = this.clock.now();
    const row: LedgerEntry = {
      seq: this.seq,
      fetchId: outcome.fetchId,
      tenantId: options?.tenantId ?? outcome.tenantId ?? 'default',
      url: outcome.origin?.url ?? 'unknown',
      status: outcome.status === 'fulfilled' ? 'fulfilled' : 'denied',
      failureClass: outcome.failureClass,
      httpStatus: outcome.origin?.httpStatus,
      priceMicros: outcome.price?.unitsMicros,
      currency: outcome.price?.currency,
      rail: outcome.rail,
      licenseId: outcome.license?.id,
      keyId: outcome.identity?.keyId,
      settlementRef: outcome.settlementRef,
      startedAt: outcome.timestamps.startedAt,
      completedAt: outcome.timestamps.completedAt,
      recordedAt: now,
    };
    this.entries.push(row);
    return row;
  }

  /** Gap-free, monotonically increasing seq. */
  lastSeq(): number {
    return this.seq;
  }

  byTenant(tenantId: string): LedgerEntry[] {
    return this.entries.filter((e) => e.tenantId === tenantId);
  }

  byUrl(url: string): LedgerEntry[] {
    return this.entries.filter((e) => e.url === url);
  }

  toRows(): LedgerEntry[] {
    return this.entries.map((e) => structuredClone(e));
  }
}

export interface LedgerSummary {
  total: number;
  fulfilled: number;
  denied: number;
  byFailureClass: Record<string, number>;
  spendMicros: number;
  byRail: Record<string, number>;
  byLicense: Record<string, number>;
}

export function summarize(rows: LedgerEntry[]): LedgerSummary {
  const s: LedgerSummary = {
    total: rows.length,
    fulfilled: 0,
    denied: 0,
    byFailureClass: {},
    spendMicros: 0,
    byRail: {},
    byLicense: {},
  };
  for (const r of rows) {
    if (r.status === 'fulfilled') s.fulfilled += 1;
    else s.denied += 1;
    if (r.failureClass) s.byFailureClass[r.failureClass] = (s.byFailureClass[r.failureClass] ?? 0) + 1;
    if (r.status === 'fulfilled' && r.priceMicros != null) s.spendMicros += r.priceMicros;
    if (r.rail) s.byRail[r.rail] = (s.byRail[r.rail] ?? 0) + 1;
    if (r.licenseId) s.byLicense[r.licenseId] = (s.byLicense[r.licenseId] ?? 0) + 1;
  }
  return s;
}

export interface ReconciliationReport {
  ok: boolean;
  problems: string[];
  checks: {
    seqGapFree: boolean;
    deniedHasFailureClass: boolean;
    fulfilledHasSettlement: boolean;
    fulfilledHasPrice: boolean;
  };
}

/**
 * Reconcile the ledger against invariants:
 *  - seq is gap-free starting at 1
 *  - every denied row has a failureClass (the three-classes invariant)
 *  - every fulfilled row has a settlementRef (we paid, we can prove it)
 *  - every fulfilled row has a price (we can bill what we paid)
 */
export function reconcile(rows: LedgerEntry[]): ReconciliationReport {
  const problems: string[] = [];

  const seqGapFree =
    rows.length === 0 ||
    rows.every((r, i) => r.seq === i + 1);

  const deniedHaveFC = rows
    .filter((r) => r.status !== 'fulfilled')
    .every((r) => r.failureClass !== undefined);

  const fulfilledHasSett = rows
    .filter((r) => r.status === 'fulfilled')
    .every((r) => (r.settlementRef ?? '').length > 0);

  const fulfilledHasPrice = rows
    .filter((r) => r.status === 'fulfilled')
    .every((r) => r.priceMicros != null && r.priceMicros > 0);

  if (!seqGapFree) problems.push('seq is not gap-free starting at 1');
  if (!deniedHaveFC) problems.push('a denied row lacks a failureClass');
  if (!fulfilledHasSett)
    problems.push('a fulfilled row lacks a settlementRef (settlement not proven)');
  if (!fulfilledHasPrice) problems.push('a fulfilled row lacks a positive price');

  return {
    ok:
      seqGapFree && deniedHaveFC && fulfilledHasSett && fulfilledHasPrice,
    problems,
    checks: { seqGapFree, deniedHasFailureClass: deniedHaveFC, fulfilledHasSettlement: fulfilledHasSett, fulfilledHasPrice },
  };
}

