/** Random fetch ids (rfc9562-style ULID would be a drop-in upgrade). */
export function makeFetchId(rand: () => number = Math.random): string {
  const alphabet = '0123456789';
  let id = '';
  for (let i = 0; i < 16; i++) id += alphabet[Math.floor(rand() * 16)]!;
  return `fetch_${id}`;
}

