export {
  parseLicense,
  deriveObligations,
  enforce,
  resolveStoreability,
} from './engine.js';
export type {
  RslTermInput,
  RslBodyLike,
  LicenseParseOptions,
  EnforcementActions,
  EnforcementResult,
} from './engine.js';

import type { Price, Quote } from './amounts.js';

/** A string constrained to a valid absolute URL at construction. */
export type UrlString = string & { readonly __brand: 'UrlString' };

export function url(value: string): UrlString {
  try {
    return new URL(value) as unknown as UrlString;
  } catch (cause) {
    throw new TypeError(`url(): invalid absolute URL: ${value}`, { cause });
  }
}

export type HeaderRecord = Record<string, string>;

/**
 * The three distinct failure classes. Today's agents collapse all of these
 * into a generic fetch failure; the broker reports each separately so the
 * cost decision is visible.
 */
export type FailureClass = 'blocked' | 'payment-required' | 'token-rejected';

export type FetchStatus = 'fulfilled' | 'denied' | 'error';

export interface FetchParams {
  url: UrlString;
  headers?: HeaderRecord;
  /** Optional tenant/subject for multi-tenant accounting. */
  tenantId?: string;
  /** Extra budget context from the caller, merged under broker policy. */
  budgetOverride?: { perCallCeilingMicros?: number; lineItemCeilingMicros?: number };
}

export type RslClauseType =
  | 'attribution'
  | 'no-store'
  | 'no-derivative-works'
  | 'no-commercial-use'
  | 'pay-per-inference'
  | 'redistribution'
  | (string & {});

export type RslClauseValue = 'required' | 'permitted' | 'forbidden' | number;

export interface RslClause {
  type: string;
  value: RslClauseValue;
  params: Record<string, string | number>;
}

/** A parsed Rights Statement Language (RSL) document. */
export interface License {
  draft: string;
  id: string;
  title?: string;
  publishedAt?: string;
  clauses: RslClause[];
  rawSource: string;
}

/**
 * Obligations the broker derives from a license and enforces/surfaces for
 * this particular fetch. Surfaced in the outcome so the caller can comply.
 */
export interface LicenseObligation {
  clause: string;
  kind: 'notice' | 'store-prohibited' | 'inference-budget' | 'forbidden' | 'permitted';
  instruction: string;
  applied?: string;
}

export interface IdentityPresentation {
  keyId: string;
  algorithm: 'ed25519';
  signedHeaders: string[];
  timestamp: string;
  /** Opaque PACT-style attestation token where the origin accepts one. */
  pactToken?: string;
}

export interface FetchOutcome {
  fetchId: string;
  status: FetchStatus;
  /** Present iff status !== 'fulfilled'. The three distinct failure classes. */
  failureClass?: FailureClass;
  reason: string;
  origin?: { url: string; httpStatus?: number };
  content?: { body: string; contentType: string; storeable: boolean; attributionNotice?: string };
  license?: License;
  obligations?: LicenseObligation[];
  price?: Price;
  quote?: Quote;
  rail?: string;
  settlementRef?: string;
  identity?: IdentityPresentation;
  tenantId?: string;
  timestamps: { startedAt: string; completedAt: string };
  error?: { code: string; message: string };
}

/** A raw ledger row — the audit surface. */
export interface LedgerEntry {
  seq: number;
  fetchId: string;
  tenantId: string;
  url: string;
  status: FetchStatus;
  failureClass?: FailureClass;
  httpStatus?: number;
  priceMicros?: number;
  currency?: string;
  rail?: string;
  licenseId?: string;
  keyId?: string;
  settlementRef?: string;
  startedAt: string;
  completedAt: string;
  recordedAt: string;
}

/**
 * A payment rail: one interface, pluggable backends.
 * Backends: x402 facilitator, Cloudflare Pay Per Crawl, self-hosted 402.
 * The interface is stable; backend field names are not (draft-caveat discipline).
 */
export interface PaymentRequest {
  url: UrlString;
  method: string;
  headers: HeaderRecord;
  contentType?: string;
}

export interface RailAuthorization {
  /** Headers the origin expects on the settled request (e.g. X-PAYMENT). */
  settlementHeaders: HeaderRecord;
  scheme: string;
  payload: string;
}

export interface RailSettlement {
  rail: string;
  settlementRef: string;
  amountMicros: number;
  currency: string;
  settledAt: string;
}

export interface PaymentRail {
  readonly id: string;
  quote(req: PaymentRequest): Promise<Quote>;
  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization>;
  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement>;
}

import { describe, expect, it } from 'vitest';
import { BudgetEngine, defaultPolicy, globMatch } from '@mwb/budget';
import { BudgetError, frozenClock } from '@mwb/core';
import type { UrlString } from '@mwb/core';

const price001 = { unitsMicros: 1_000, currency: 'USD' }; // 0.001
const u1 = 'https://news.example.com/wire/headline' as UrlString;

describe('BudgetEngine.preflight', () => {
  it('lets cheap quotes through', () => {
    const engine = new BudgetEngine({ clock: frozenClock() });
    expect(() => engine.preflight('tenant-a', price001, u1)).not.toThrow();
  });

  it('blocks a quote above the per-call ceiling', () => {
    const engine = new BudgetEngine({ clock: frozenClock() });
    expect(() => engine.preflight('tenant-a', { unitsMicros: 100_000, currency: 'USD' })).toThrowError(
      BudgetError
    );
  });

  it('blocks once the hourly tenant ceiling is consumed', () => {
    const clock = frozenClock();
    const policy = {
      ...defaultPolicy,
      perCallCeilingMicros: 10_000,
      hourlyTenantCeilingMicros: 2_000,
    };
    const engine = new BudgetEngine({ clock, policy });
    engine.preflight('t', price001);
    engine.recordPaid('t', price001, u1);
    expect(() => engine.preflight('t', price001)).toThrow(/hourly tenant ceiling/);
  });

  it('lets the hourly window roll over', () => {
    let t = '2026-08-18T00:00:00.000Z';
    const clock = { now: () => t };
    const policy = {
      ...defaultPolicy,
      perCallCeilingMicros: 10_000,
      hourlyTenantCeilingMicros: 2_000,
    };
    const engine = new BudgetEngine({ clock, policy });
    engine.recordPaid('t', price001, u1);
    engine.recordPaid('t', { unitsMicros: 1_500, currency: 'USD' }, u1);
    expect(() => engine.preflight('t', price001)).toThrow();
    t = '2026-08-18T02:00:00.000Z';
    expect(() => engine.preflight('t', price001)).not.toThrow();
  });

  it('enforces per-line-item daily ceilings', () => {
    const clock = frozenClock();
    const policy = {
      ...defaultPolicy,
      lineItems: [
        { match: '*.news.example.com/*', dailyCeilingMicros: 2_500, lifetimeCeilingMicros: 5_000, currency: 'USD' },
      ],
    };
    const engine = new BudgetEngine({ clock, policy });
    for (let i = 0; i < 2; i++) {
      engine.preflight('t', price001, u1);
      engine.recordPaid('t', price001, u1);
    }
    expect(() => engine.preflight('t', price001, u1)).toThrow(/line-item daily/);
    // Other hosts are unaffected.
    const u2 = 'https://other.example.org/a' as UrlString;
    engine.recordPaid('t', price001, u2);
  });

  it('raises a stable code on denial', () => {
    const engine = new BudgetEngine({ clock: frozenClock(), policy: { ...defaultPolicy, hourlyTenantCeilingMicros: 500 } });
    let caught: unknown;
    try {
      engine.recordPaid('t', { unitsMicros: 1_000, currency: 'USD' }, u1);
      engine.preflight('t', price001, u1);
    } catch (err) {
      caught = err;
    }
    expect(caught).toBeInstanceOf(BudgetError);
  });

  it('rejects cross-currency quotes', () => {
    const engine = new BudgetEngine({ clock: frozenClock() });
    expect(() => engine.preflight('t', { unitsMicros: 1_000, currency: 'EUR' })).toThrow(/currency/i);
  });
});

describe('globMatch', () => {
  it('matches host + path with *', () => {
    expect(globMatch('*.news.example.com/*', 'news.example.com/wire/headline')).toBe(true);
    expect(globMatch('news.example.com/*', 'other.example.org/a')).toBe(false);
  });
});

describe('meter snapshot', () => {
  it('tracks spend per tenant and per line item', () => {
    const clock = frozenClock();
    const engine = new BudgetEngine({
      clock,
      policy: {
        ...defaultPolicy,
        lineItems: [
          { match: 'news.example.com/*', dailyCeilingMicros: 100_000, lifetimeCeilingMicros: 100_000, currency: 'USD' },
        ],
      },
    });
    engine.recordPaid('t', price001, u1);
    const snap = engine.snapshot('t');
    expect(snap.hourly.spentMicros).toBe(1_000);
    expect(snap.daily.spentMicros).toBe(1_000);
    expect(snap.lineItems['news.example.com/*'].lifetimeMicros).toBe(1_000);
    // Snapshot is defensive.
    snap.hourly.spentMicros = 999_999;
    expect(engine.snapshot('t').hourly.spentMicros).toBe(1_000);
  });
});

